/* ================= shared chart helpers ================= */
function series(c, years) {
  const end = T(c.priceDate), start = end - years * 365.25 * 864e5;
  const bvAt = d => ([...c.q].reverse().find(q => q.d <= d && q.bvps != null) || c.q.find(q => q.bvps != null) || {}).bvps;
  const pts = c.px && c.px.length > 8 ? c.px.map(([d, p]) => ({ t: T(d), d, price: p, bvps: bvAt(d) })) : c.q.filter(q => q.price != null).map(q => ({ t: T(q.d), d: q.d, price: q.price, bvps: q.bvps }));
  for (const x of c.extra || []) { const bq = [...c.q].reverse().find(q => q.d <= x.d) || c.q[0]; pts.push({ t: T(x.d), d: x.d, price: x.price, bvps: bq.bvps, label: x.label }); }
  pts.sort((a, b) => a.t - b.t);
  pts.push({ t: end, d: c.priceDate, price: c.price, bvps: c.q.at(-1).bvps, now: true });
  const inR = pts.filter(p => p.t >= start);
  return { pts: inR.length >= 2 ? inR : pts, books: c.q.filter(q => q.bvps != null).map(q => ({ t: T(q.d), v: q.bvps })) };
}
function monotone(P) {
  const n = P.length; if (n < 2) return ""; if (n === 2) return `M${P[0][0]},${P[0][1]}L${P[1][0]},${P[1][1]}`;
  const dx = [], dy = [], m = [], s = [];
  for (let i = 0; i < n - 1; i++) { dx.push(P[i + 1][0] - P[i][0]); dy.push(P[i + 1][1] - P[i][1]); s.push(dy[i] / dx[i]); }
  m.push(s[0]); for (let i = 1; i < n - 1; i++) m.push(s[i - 1] * s[i] <= 0 ? 0 : (s[i - 1] + s[i]) / 2); m.push(s[n - 2]);
  for (let i = 0; i < n - 1; i++) { if (s[i] === 0) { m[i] = m[i + 1] = 0; continue; } const a = m[i] / s[i], b = m[i + 1] / s[i], h = a * a + b * b; if (h > 9) { const k = 3 / Math.sqrt(h); m[i] = k * a * s[i]; m[i + 1] = k * b * s[i]; } }
  let d = `M${P[0][0]},${P[0][1]}`;
  for (let i = 0; i < n - 1; i++) d += `C${P[i][0] + dx[i] / 3},${P[i][1] + m[i] * dx[i] / 3} ${P[i + 1][0] - dx[i] / 3},${P[i + 1][1] - m[i + 1] * dx[i] / 3} ${P[i + 1][0]},${P[i + 1][1]}`;
  return d;
}
function xraySVG(c, years, W, H, pad, mini) {
  const { pts, books } = series(c, years), t0 = pts[0].t, t1 = pts.at(-1).t;
  const bIn = books.filter(b => b.t >= t0 - 100 * 864e5 && b.t <= t1);
  const vals = [...pts.map(p => p.price), ...pts.map(p => p.bvps), ...bIn.map(b => b.v), 0];
  const lo = Math.min(...vals), hi = Math.max(...vals) * 1.06;
  const X = t => pad.l + (t - t0) / Math.max(1, t1 - t0) * (W - pad.l - pad.r);
  const Y = v => pad.t + (hi - v) / (hi - lo || 1) * (H - pad.t - pad.b);
  const priceD = monotone(pts.map(p => [X(p.t), Y(p.price)]));
  const steps = books.filter(b => b.t <= t1), first = [...steps].reverse().find(b => b.t <= t0) || steps[0];
  let bd = `M${X(t0)},${Y(first.v)}`; for (const b of steps) if (b.t > t0) bd += `H${X(b.t)}V${Y(b.v)}`; bd += `H${X(t1)}`;
  const zero = Y(0), base = H - pad.b, id = mini ? "m" + c.t : "f";
  const st = (() => { const r = (hi - lo) / 4, p = 10 ** Math.floor(Math.log10(r || 1)), m = r / p; return (m < 1.5 ? 1 : m < 3 ? 2 : m < 7 ? 5 : 10) * p; })();
  const ticks = []; for (let v = Math.ceil(lo / st) * st; v <= hi; v += st) ticks.push(v);
  return { pts, X, Y, ticks, H, svg: `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" ${mini ? 'aria-hidden="true"' : `role="img" aria-label="${esc(c.name)} share price versus book value per share"`}>
    <defs><linearGradient id="pg${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9FD0FF" stop-opacity=".22"/><stop offset="1" stop-color="#F4F7FA" stop-opacity="0"/></linearGradient></defs>
    ${mini ? "" : ticks.map(v => `<line x1="0" x2="${W}" y1="${Y(v)}" y2="${Y(v)}" stroke="rgba(111,178,242,.14)" stroke-dasharray="2 5" vector-effect="non-scaling-stroke"/>`).join("")}
    ${!mini && lo < 0 ? `<line x1="${pad.l}" x2="${W - pad.r}" y1="${zero}" y2="${zero}" stroke="#3A4654" stroke-dasharray="3 4"/>` : ""}
    <g class="rv"><path d="${priceD}L${X(t1)},${base}L${X(t0)},${base}Z" fill="url(#pg${id})"/>
    <path d="${bd}V${zero}H${X(t0)}Z" fill="rgba(54,226,242,.22)"/>
    <path class="bl" d="${bd}" fill="none" stroke="#36E2F2" stroke-width="${mini ? 1.6 : 2.4}" vector-effect="non-scaling-stroke"/>
    <path class="pl" d="${priceD}" fill="none" stroke="#F4F7FA" stroke-width="${mini ? 1.6 : 2.4}" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></g>
    ${mini ? "" : `<g id="scrub" style="display:none"><line id="sl" y1="${pad.t - 6}" y2="${base}" stroke="#4A5866" stroke-width="1" vector-effect="non-scaling-stroke"/><circle id="sp" r="5" fill="#F4F7FA" stroke="#06080B" stroke-width="2"/><circle id="sb" r="5" fill="#36E2F2" stroke="#06080B" stroke-width="2"/></g>`}
  </svg>` };
}
const miniChart = (c, w, h) => xraySVG(c, 5, w, h, { l: 1, r: 1, t: 3, b: 3 }, true).svg.replace("<svg ", `<svg style="width:100%;height:${h}px" `);

