          <path class="cline" d="M16 62 L26 57 L33 60 L42 47 L50 51 L58 38 L66 42 L76 27 L84 31" fill="none" stroke="#FFFFFF" stroke-width=".75" stroke-linejoin="round" stroke-linecap="round"/>
