const TIE = { pe: ["Private equity", "#FF6FB5"], alt: ["Alternative asset manager", "#FF6FB5"], credit: ["Credit / distressed", "#FF6FB5"], inv: ["Other investment firm", "#8796A6"], vc: ["Venture capital", "#8796A6"] };
const flagged = m => (m.ties || []).some(t => ["pe", "alt", "credit"].includes(t[1]));
function boardTab(c) {
  const B = BOARDS[c.t]; if (!B) return `<div class="card"><p class="note">No board data yet.</p></div>`;
  const ms = B.m.map(([n, r, k = "out", f = "", ties = []]) => ({ n, r, k, f, ties }));
  const chair = ms.find(m => m.f === "chair"), lead = ms.find(m => m.f === "lead"), execs = ms.filter(m => m.k === "exec"), outs = ms.filter(m => m.k !== "exec");
  const flg = ms.filter(flagged), firms = [...new Set(flg.flatMap(m => m.ties.filter(t => ["pe", "alt", "credit"].includes(t[1])).map(t => t[0])))];
  const ini = n => { const w = n.replace(/\b(III|Jr\.?)\b/g, "").split(/\s+/).filter(x => /^[A-Z][a-z]/.test(x)); return (w[0]?.[0] || "") + (w.length > 1 ? w.at(-1)[0] : ""); };
  const person = m => { const fl = flagged(m), main = m.ties.filter(t => ["pe", "alt", "credit"].includes(t[1])), other = m.ties.filter(t => !["pe", "alt", "credit"].includes(t[1]));
    const lk = personLinks(c.t, m.n);
    return `<div class="person${fl ? " flag" : ""}" id="${pid(m.n)}"><span class="av ${m.k === "exec" ? "ex" : ""}${fl ? " fl" : ""}">${esc(ini(m.n))}</span><div style="min-width:0"><b>${esc(m.n)}</b><span>${esc(m.r)}</span>
      ${main.map(t => `<div class="tie hot"><em>${TIE[t[1]][0]}</em> <strong>${esc(t[0])}</strong> · ${esc(t[2])}</div>`).join("")}
      ${other.map(t => `<div class="tie"><em>${TIE[t[1]][0]}</em> ${esc(t[0])} · ${esc(t[2])}</div>`).join("")}
      ${lk.length ? `<div class="chips">${lk.map(([sec, l, k]) => `<button class="pchip ${k}" data-jumpsec="sec-${sec}">${esc(l)} ↑</button>`).join("")}</div>` : ""}</div>
      ${m.f === "chair" ? `<em class="tag ch">Chair</em>` : m.f === "lead" ? `<em class="tag ld">Lead</em>` : m.k === "exec" ? `<em class="tag ex">Runs it</em>` : fl ? `<em class="tag pe">PE tie</em>` : ""}</div>`; };
  const order = [chair, ...ms.filter(m => m !== chair && m.k === "exec"), ...ms.filter(m => m !== chair && m.k !== "exec" && flagged(m)), ...ms.filter(m => m !== chair && m.k !== "exec" && !flagged(m))].filter(Boolean);
  const W = 420, H = 34, n = ms.length, seg = W / n;
  const sorted = [...ms].sort((a, b) => (a.k === "exec" ? 0 : flagged(a) ? 1 : 2) - (b.k === "exec" ? 0 : flagged(b) ? 1 : 2));
  return `
    <div class="card"><span class="label">Board of directors</span>
      <div class="verdict" style="font-size:22px">${n} directors. ${execs.length === 1 ? "1 runs the company" : execs.length + " run the company"}, ${outs.length} ${outs.length === 1 ? "is" : "are"} from outside.</div>
      <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${execs.length} executives, ${flg.length} with private equity or credit ties, ${n} directors in total">${sorted.map((m, i) => `<rect x="${i * seg + 1.5}" y="4" width="${seg - 3}" height="26" rx="6" fill="${m.k === "exec" ? "#FFB547" : "#36E2F2"}" opacity="${m.k === "exec" ? 1 : .5}" ${flagged(m) ? 'stroke="#FF6FB5" stroke-width="3"' : ""}/>`).join("")}</svg>
      <div class="legend"><span><i style="background:#FFB547"></i>Executives</span><span><i style="background:rgba(54,226,242,.5)"></i>Outside directors</span><span><i style="background:#FF6FB5"></i>PE, credit or alt-asset tie</span></div>
      <div class="stats">
        <div><span>Chair</span><span>${chair ? esc(chair.n) : "None"}</span></div>
        <div><span>CEO also chairs?</span><span>${B.ceoChair == null ? "No chair" : B.ceoChair ? "Yes" : "No"}</span></div>
        ${lead ? `<div><span>Lead independent</span><span>${esc(lead.n)}</span></div>` : ""}
        <div><span>Outside share</span><span>${Math.round(outs.length / n * 100)}%</span></div>
      </div>
      ${B.control ? `<p class="note" style="color:var(--warn)">${esc(B.control)} <a href="${B.controlSrc[1]}" target="_blank" rel="noopener" style="color:var(--books)">Source</a></p>` : ""}
    </div>
    <div class="card pecard" id="sec-pe"><span class="label" style="color:#FF8FC6">Private equity and credit ties</span>
      <div class="verdict" style="font-size:20px">${flg.length ? `${flg.length} of ${n} directors ${flg.length === 1 ? "has" : "have"} ties to private equity, credit or alternative asset firms.` : "No directors with private equity, credit or alternative-asset ties found."}</div>
      ${firms.length ? `<div class="firms">${firms.map(f => `<span>${esc(f)}</span>`).join("")}</div>` : ""}
      <p class="note">Current or past roles, as described in each director's biography in the company's filings. A tie isn't wrongdoing. It shows whose playbook may shape decisions on debt, buybacks, asset sales and deals.</p>
    </div>
    ${boardExtra(c)}
    <div class="card"><h2>Who's on the board</h2><div class="people">${order.map(person).join("")}</div>
      <p class="note" style="font-size:12.5px">Source: ${B.src ? `<a href="${B.src[1]}" target="_blank" rel="noopener" style="color:var(--books)">${esc(B.src[0])}</a>` : "directors' SEC Form 3 and 4 filings (no proxy statement yet)"}. Board as of ${LIVE.ok ? fmtD(LIVE.built) : "Oct 2026"}.</p></div>
    <div class="card"><h2>Why the board matters for the balance sheet</h2><p class="note">The board hires and fires the CEO and signs off on the big money moves you see in the balance sheet: buybacks, selling new shares, taking on debt and big acquisitions. When the CEO also chairs the board, or one person controls most of the votes, there are fewer outside checks on those decisions.</p></div>`;
}

