  const W = 340, H = 190, pad = { l: 46, r: 10, t: 12, b: 24 };
  const lo = log ? lo0 / 1.15 : Math.max(0, lo0 - (hi0 - lo0) * .08), hi = log ? hi0 * 1.15 : hi0 + (hi0 - lo0) * .08;
  const f = v => log ? Math.log10(v) : v, X = t => pad.l + (t - t0) / (t1 - t0) * (W - pad.l - pad.r), Y = v => pad.t + (f(hi) - f(v)) / (f(hi) - f(lo)) * (H - pad.t - pad.b);
  const ticks = [];
  if (log) { for (let e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++) for (const k of [1, 2, 5]) { const v = k * 10 ** e; if (v >= lo && v <= hi) ticks.push(v); } }
  else { const r = (hi - lo) / 4, p = 10 ** Math.floor(Math.log10(r)), s = (r / p < 1.5 ? 1 : r / p < 3 ? 2 : r / p < 7 ? 5 : 10) * p; for (let v = Math.ceil(lo / s) * s; v <= hi; v += s) ticks.push(v); }
