  const opts = [["ipo", "Since IPO", M.starts.ipo], ["merger", "Merger", M.merger], ["split", M.split?.rev ? "Rev. split" : "Split", M.split], ["future", "Future", X.DIL[c.t]?.items.length]];
  const seg = `<div class="seg" role="group" aria-label="Start point">${opts.map(([k, l, o]) => `<button data-mt="${k}" class="${S.mt === k ? "on" : ""}" ${o ? "" : "disabled"} aria-pressed="${S.mt === k}">${l}</button>`).join("")}</div>`;
  if (S.mt === "future") return seg + futureCard(c);
