/* ---------- price vs. books visuals ---------- */
const GL = [.3, 100], gpos = v => (Math.log(Math.max(GL[0], Math.min(GL[1], v))) - Math.log(GL[0])) / (Math.log(GL[1]) - Math.log(GL[0])) * 100;
