const FREE_BETA = (window.XRAY_CONFIG || {}).freeBeta !== false;
const PRICE = { month: { p: "$4.99", per: "per month", sub: "Billed monthly" }, year: { p: "$39.99", per: "per year", sub: "$3.33 a month, billed yearly", save: "SAVE 33%" } };
