const claimNew = ts => { let last = null; for (const t of ts) { if (XR.get().includes(t)) continue; const n = claimXray(t); if (n) last = [t, n]; } if (last) pickToast(...last); };
const claimXray = t => { if (isPro()) return null; const l = XR.get(); if (l.includes(t)) return l.indexOf(t) + 1; if (l.length >= FREE_XRAYS) return null; l.push(t); XR.set(l); return l.length; };
