document.addEventListener("click", e => {
  const t = e.target.closest("[data-ob],[data-obmode],[data-obsso],[data-obinfo],[data-mfa],[data-obsend],[data-obverify],[data-obbio],[data-exp],[data-like],[data-pickob],[data-obfinish],[data-obenter],[data-unlock],[data-unlockpw],[data-acct],[data-closesheet],[data-togbio],[data-wlike],[data-replay],[data-signout]");
  if (!t) return; const d = t.dataset; e.stopImmediatePropagation();
  if (d.ob) return obGo(d.ob);
  if (d.obmode) { OB.mode = d.obmode; return obGo("account"); }
  if (d.obsso) { OB.mode = "create"; OB.email = OB.email || (d.obsso === "passkey" ? "" : "you@" + d.obsso.toLowerCase() + ".example"); OB.name = OB.name || "Investor"; sendCode(); OB.mfa = "app"; OB.err = ""; return obGo(d.obsso === "passkey" ? "bio" : "mfa"); }
  if (d.obinfo) { OB.err = "In the full app this sends a reset link to your email."; return render(); }
  if (d.mfa) { OB.mfa = d.mfa; OB.err = ""; return render(); }
  if (d.obsend) { return authSend(); }
  if (d.obverify) { OB.code = [...document.querySelectorAll("#codebox input")].map(x => x.value).join(""); return verify(); }
  if (d.obbio) { OB.scanning = true; render(); setTimeout(() => { OB.scanning = false; OB.bio = true; buzz(); render(); }, 1400); return; }
  if (d.exp) { OB.exp = d.exp; return render(); }
  if (d.like) { OB.likes = OB.likes.includes(d.like) ? OB.likes.filter(x => x !== d.like) : [...OB.likes, d.like]; return render(); }
  if (d.pickob) { OB.picks = OB.picks.includes(d.pickob) ? OB.picks.filter(x => x !== d.pickob) : [...OB.picks, d.pickob]; return render(); }
  if (d.obfinish) { finishIntro(); return obGo("done"); }
  if (d.obenter) { document.body.classList.remove("intro"); go("search"); return maybeWelcome(); }
  if (d.unlock) { S.unlocking = true; render(); setTimeout(() => { S.unlocking = false; buzz(); document.body.classList.remove("intro"); go("search"); }, 1300); return; }
  if (d.unlockpw) { OB.mode = "signin"; OB.email = (ACCT.get() || {}).email || ""; S.view = "intro"; return obGo("account"); }
  if (d.acct) { const el = $("#sheet"); el.innerHTML = accountSheet(); return; }
  if (d.closesheet) { $("#sheet").innerHTML = ""; return; }
  if (d.wlike) { const a = ACCT.get(), l = a.likes || []; a.likes = l.includes(d.wlike) ? l.filter(x => x !== d.wlike) : [...l, d.wlike]; ACCT.set(a); S.cmTouched = false; render(); $("#sheet").innerHTML = accountSheet(); return; }
  if (d.togbio) { const a = ACCT.get(); a.bio = !a.bio; ACCT.set(a); $("#sheet").innerHTML = accountSheet(); return; }
  if (d.replay) { $("#sheet").innerHTML = ""; Object.assign(OB, { step: "splash", picks: [...S.home] }); S.view = "intro"; return render(); }
  if (d.signout) { $("#sheet").innerHTML = ""; ACCT.clear(); store.set("onboarded", false); Object.assign(OB, { step: "splash", email: "", name: "", bio: false, picks: [], likes: [], exp: "" }); S.view = "intro"; return render(); }
}, true);

