document.addEventListener("click", e => {
  const j = e.target.closest("[data-jump],[data-jumpsec]");
  if (j) { const el = document.getElementById(j.dataset.jump || j.dataset.jumpsec); if (el) { el.scrollIntoView?.({ behavior: "smooth", block: "center" }); el.classList.remove("flash"); void el.offsetWidth; el.classList.add("flash"); } return; }
  const hb = e.target.closest("[data-rm],[data-add],[data-a=edithome],[data-a=addopen],[data-a=addall],[data-a=resethome],[data-a=homeadd]");
  if (hb) { const d = hb.dataset;
    const full = !isPro() && S.home.length >= FREE_HOME;
    if (full && (d.add || d.a === "addall" || (d.a === "homeadd" && !S.home.includes(S.t)))) return openPaywall("home");
    if (d.rm) S.home = S.home.filter(t => t !== d.rm);
    else if (d.add) { S.home = [...S.home, d.add]; claimNew([d.add]); if (FEATURED.every(t => S.home.includes(t)) || (!isPro() && S.home.length >= FREE_HOME)) S.addOpen = false; }
    else if (d.a === "edithome") { S.editHome = !S.editHome; if (!S.editHome) S.addOpen = false; }
    else if (d.a === "addopen") S.addOpen = !S.addOpen;
    else if (d.a === "addall") { S.home = [...S.home, ...FEATURED.filter(t => !S.home.includes(t))].slice(0, isPro() ? 1e9 : FREE_HOME); S.addOpen = false; }
    else if (d.a === "resethome") { S.home = FEATURED.slice(0, isPro() ? 1e9 : FREE_HOME); S.addOpen = false; S.editHome = false; }
    else if (d.a === "homeadd") { const t = S.t; const adding = !S.home.includes(t); S.home = adding ? [...S.home, t] : S.home.filter(x => x !== t); saveHome(); if (adding) claimNew([t]); viewCompany(); return; }
    saveHome(); buzz(); drawHome(); return; }
  const cmb = e.target.closest("[data-cm]"); if (cmb) { S.cm = cmb.dataset.cm; S.cmTouched = true; viewCompare(); return; }
  const fl = e.target.closest(".fline"); if (fl) { S.tab = fl.dataset.tab; if (S.tab === "mt" && fl.dataset.sec === "future") S.mt = "future"; viewCompany(); const sec = fl.dataset.sec; setTimeout(() => { const el = sec && sec !== "future" ? document.getElementById(sec) : document.querySelector(".tabs"); el?.scrollIntoView?.({ behavior: "smooth", block: sec && sec !== "future" ? "center" : "start" }); if (el && sec && sec !== "future") { el.classList.add("flash"); } }, 60); return; }
  const m = e.target.closest("[data-mt]"); if (m && !m.disabled) { S.mt = m.dataset.mt; renderTab(co(S.t)); return; }
  const b = e.target.closest("[data-open],[data-nav],[data-tab],[data-range],[data-a],[data-pick]"); if (!b) return;
  if (b.dataset.open) { openCo(b.dataset.open); if (b.dataset.tabgo) { S.tab = b.dataset.tabgo; viewCompany(); } }
  else if (b.dataset.nav) go(b.dataset.nav);
  else if (b.dataset.tab) { S.tab = b.dataset.tab; b.scrollIntoView?.({ inline: "nearest", block: "nearest" }); document.querySelectorAll(".tabs [data-tab]").forEach(x => { x.classList.toggle("on", x.dataset.tab === S.tab); x.setAttribute("aria-selected", x.dataset.tab === S.tab); }); renderTab(co(S.t)); }
  else if (b.dataset.range) { S.range = +b.dataset.range; const c = co(S.t); drawChart(c); setHead(c, null); document.querySelectorAll("[data-range]").forEach(x => x.classList.toggle("on", x === b)); }
  else if (b.dataset.a === "cmp") { S.compare = S.compare.includes(S.t) ? S.compare.filter(t => t !== S.t) : [...S.compare, S.t]; store.set("compare", S.compare); const on = S.compare.includes(S.t); b.classList.toggle("on", on); b.setAttribute("aria-pressed", on); b.textContent = on ? "✓ In Compare" : "+ Compare"; }
  else if (b.dataset.pick) { const t = b.dataset.pick; S.compare = S.compare.includes(t) ? S.compare.filter(x => x !== t) : [...S.compare, t]; store.set("compare", S.compare); viewCompare(); }
});
